SET NAMES utf8mb4;
-- 1) 确保 tpo 记录存在
INSERT INTO tpo (tpo_no, title, create_time) SELECT 'TPO01', 'TPO 01 模拟套题', NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM tpo WHERE tpo_no = 'TPO01');
SET @tpo_id = (SELECT id FROM tpo WHERE tpo_no = 'TPO01' LIMIT 1);

-- 文章：示例 - 城市夜间照明的影响
INSERT INTO tpo_section (tpo_id, type, content_text, audio_url, create_time) VALUES (@tpo_id, 'reading', 'For most of human history, the night was genuinely dark. Only in the last century did artificial light become cheap enough to illuminate streets, homes, and workplaces after sunset. The change brought obvious benefits: safer roads, longer working hours, and livelier public spaces. Yet researchers have begun to notice a subtler cost. Many insects navigate by faint celestial cues, and a bright streetlamp can draw them into wasteful orbits until they die of exhaustion. Birds that migrate at night face a similar problem, circling illuminated towers instead of following their routes.

Some cities have responded by dimming lamps during low-traffic hours or by choosing wavelengths that attract fewer insects. Such measures rarely save much money, but they do reduce ecological disruption, and several studies report that residents barely notice the difference in visibility.', NULL, NOW());
SET @section_id = LAST_INSERT_ID();
INSERT INTO tpo_question (section_id, module_type, type, question_type, question_title, option_a, option_b, option_c, option_d, answer, analysis, create_time, passage_title, passage_content) SELECT @section_id, 'reading', 'VOCABULARY', 'VOCABULARY', 'The word "subtler" in the passage is closest in meaning to', 'less obvious', 'more expensive', 'more dangerous', 'less permanent', 'A', '原文先说人工照明带来 obvious benefits，接着用 Yet 转折引出 a subtler cost，subtler 与前面的 obvious 构成对照，意思是"不那么明显的"，故选 A。', NOW(), '阅读 Passage 1（示例）', 'For most of human history, the night was genuinely dark. Only in the last century did artificial light become cheap enough to illuminate streets, homes, and workplaces after sunset. The change brought obvious benefits: safer roads, longer working hours, and livelier public spaces. Yet researchers have begun to notice a subtler cost. Many insects navigate by faint celestial cues, and a bright streetlamp can draw them into wasteful orbits until they die of exhaustion. Birds that migrate at night face a similar problem, circling illuminated towers instead of following their routes.

Some cities have responded by dimming lamps during low-traffic hours or by choosing wavelengths that attract fewer insects. Such measures rarely save much money, but they do reduce ecological disruption, and several studies report that residents barely notice the difference in visibility.' FROM DUAL;
INSERT INTO tpo_question (section_id, module_type, type, question_type, question_title, option_a, option_b, option_c, option_d, answer, analysis, create_time, passage_title, passage_content) SELECT @section_id, 'reading', 'INFERENCE', 'INFERENCE', 'What can be inferred about the measures some cities have taken?', 'They cost more than keeping all lamps at full brightness.', 'They are unlikely to be adopted because residents object.', 'They can reduce harm to wildlife without greatly changing how dark streets feel.', 'They have already eliminated the problem of migrating birds.', 'C', '原文说 measures rarely save much money, but they do reduce ecological disruption，且 residents barely notice the difference in visibility，说明生态收益明显、观感变化很小，故选 C。A 曲解"省不了多少钱"；B 与"居民几乎察觉不到"矛盾；D 说得过于彻底。', NOW(), '阅读 Passage 1（示例）', 'For most of human history, the night was genuinely dark. Only in the last century did artificial light become cheap enough to illuminate streets, homes, and workplaces after sunset. The change brought obvious benefits: safer roads, longer working hours, and livelier public spaces. Yet researchers have begun to notice a subtler cost. Many insects navigate by faint celestial cues, and a bright streetlamp can draw them into wasteful orbits until they die of exhaustion. Birds that migrate at night face a similar problem, circling illuminated towers instead of following their routes.

Some cities have responded by dimming lamps during low-traffic hours or by choosing wavelengths that attract fewer insects. Such measures rarely save much money, but they do reduce ecological disruption, and several studies report that residents barely notice the difference in visibility.' FROM DUAL;

